sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var r = new sn_ws.RESTMessageV2('x_2098628_ds_ent_0.Discord Access Notification', 'Send Discord Notification');
        
        // Execute outbound REST call
        var response = r.execute();
        var httpStatus = response.getStatusCode();
        
        gs.info('Discord Webhook Executed with Status: ' + httpStatus);
        
        if (httpStatus === 204 || httpStatus === 200) {
            outputs.status = 'Success';
        } else {
            outputs.status = 'Failed';
            gs.error('Discord Webhook failed with status: ' + httpStatus);
        }
    } catch (ex) {
        outputs.status = 'Error';
        gs.error('Discord Webhook Exception: ' + ex.message);
    }
})(inputs, outputs);

